  function renderReports(){for(const type of ['daily','weekly']){const current=state.reports.find(r=>r.type===type&&r.key===(type==='daily'?`daily:${dateKey(today)}`:`weekly:${startOfWeek(today)}`));if(!current)continue;const stamp=new Date(current.generatedAt).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});$(`#${type}-report-meta`).textContent=`Updated ${stamp}`;$(`#${type}-report-text`).textContent=current.text;}}
